package com.oibsip.onlineexam.ui;
import javax.swing.*; import java.awt.*; import com.oibsip.onlineexam.model.User;
public class LoginPanel extends JPanel {private final MainFrame f; private final JTextField user=new JTextField(); private final JPasswordField pass=new JPasswordField(); public LoginPanel(MainFrame x){f=x;setLayout(new GridBagLayout());JPanel card=new JPanel(new GridBagLayout());card.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(210,215,225)),BorderFactory.createEmptyBorder(30,35,30,35)));GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(8,8,8,8);g.fill=GridBagConstraints.HORIZONTAL;JLabel t=new JLabel("Online Examination System",SwingConstants.CENTER);t.setFont(new Font("SansSerif",Font.BOLD,26));g.gridx=0;g.gridy=0;g.gridwidth=2;card.add(t,g);g.gridwidth=1;g.gridy++;card.add(new JLabel("Username"),g);g.gridx=1;card.add(user,g);g.gridx=0;g.gridy++;card.add(new JLabel("Password"),g);g.gridx=1;card.add(pass,g);JButton login=new JButton("Login"),clear=new JButton("Clear"),exit=new JButton("Exit");g.gridx=0;g.gridy++;card.add(login,g);g.gridx=1;card.add(clear,g);g.gridy++;card.add(exit,g);login.addActionListener(e->doLogin());clear.addActionListener(e->{user.setText("");pass.setText("");});exit.addActionListener(e->System.exit(0));add(card);}private void doLogin(){User u=f.auth().authenticate(user.getText(),new String(pass.getPassword()));if(u==null){JOptionPane.showMessageDialog(f,"Invalid username or password.","Login Failed",JOptionPane.ERROR_MESSAGE);return;}f.session().login(u);f.show(MainFrame.PROFILE);}}
